/* @arkzen:meta
name: hello-native
version: 1.0.0
description: Native-only starter tatemono. Two screens — home and about. No auth, no backend.
auth: false
*/

/* @arkzen:meta:native
label: Hello Native
description: Arkzen native starter — index + about screens
expo:
  bundle_id: com.arkzen.hellonative
  scheme: hellonative
  version: 1.0.0
  orientation: portrait
  status_bar_style: dark
*/

/* @arkzen:native:config
theme:
  primary: "#6366f1"
  background: "#fafaf9"
  surface: "#ffffff"
  text: "#0f172a"
  muted: "#94a3b8"
*/

/* @arkzen:native:components:shared */

/* @arkzen:import:expo */
import React, { useState } from 'react'
import {
  View,
  Text,
  TouchableOpacity,
  Pressable,
} from 'react-native'
import { useRouter } from 'expo-router'
/* @arkzen:import:expo:end */

/* @arkzen:import:rn */
import React, { useState } from 'react'
import {
  View,
  Text,
  TouchableOpacity,
  Pressable,
} from 'react-native'
/* @arkzen:import:rn:end */

// ── Pill badge ────────────────────────────────────────────────
export const Badge = ({ label }: { label: string }) => (
  <View className="px-3 py-1 bg-indigo-100 rounded-full self-start">
    <Text className="text-xs font-semibold text-indigo-600 tracking-wide">
      {label}
    </Text>
  </View>
)

// ── Primary button ────────────────────────────────────────────
export const PrimaryButton = ({
  label,
  onPress,
  disabled = false,
}: {
  label: string
  onPress: () => void
  disabled?: boolean
}) => (
  <TouchableOpacity
    onPress={onPress}
    disabled={disabled}
    activeOpacity={0.82}
    className={`rounded-2xl py-4 px-6 items-center ${
      disabled ? 'bg-indigo-200' : 'bg-indigo-500'
    }`}
  >
    <Text className="text-white font-semibold text-base tracking-wide">
      {label}
    </Text>
  </TouchableOpacity>
)

// ── Ghost button ──────────────────────────────────────────────
export const GhostButton = ({
  label,
  onPress,
}: {
  label: string
  onPress: () => void
}) => (
  <Pressable onPress={onPress} className="rounded-2xl py-4 px-6 items-center border border-neutral-200">
    <Text className="text-neutral-600 font-medium text-base">{label}</Text>
  </Pressable>
)

// ── Section card ──────────────────────────────────────────────
export const Card = ({
  title,
  body,
}: {
  title: string
  body: string
}) => (
  <View className="bg-white rounded-2xl p-5 border border-neutral-100 shadow-sm mb-3">
    <Text className="text-sm font-semibold text-neutral-800 mb-1">{title}</Text>
    <Text className="text-sm text-neutral-500 leading-5">{body}</Text>
  </View>
)

/* @arkzen:native:components:shared:end */


/* @arkzen:native:page:index */

const IndexScreen = () => {
  const router = useRouter()

  return (
    <View className="flex-1 bg-neutral-50 px-6 pt-14 pb-10">

      {/* Header */}
      <View className="mb-10">
        <Badge label="Arkzen Native v1.0" />
        <Text className="text-4xl font-bold text-neutral-900 mt-4 leading-tight">
          Hello,{'\n'}Native. 👋
        </Text>
        <Text className="text-base text-neutral-500 mt-3 leading-6">
          Your first Arkzen native tatemono is running. Drop your UI in the native:page block.
        </Text>
      </View>

      {/* Feature cards */}
      <View className="mb-8">
        <Card
          title="📦 Isolated module"
          body="This screen lives in tatemonos/hello-native/core.tsx — zero interference with other tatemonos."
        />
        <Card
          title="🎨 NativeWind styling"
          body="All className utilities available. No StyleSheet boilerplate needed."
        />
        <Card
          title="⚡ Expo Router"
          body="File-based routing auto-generated by the engine. Add a native:page block, get a route."
        />
      </View>

      {/* Actions */}
      <View className="gap-y-3">
        <PrimaryButton
          label="Go to About"
          onPress={() => router.push('/hello-native/about' as any)}
        />
      </View>

    </View>
  )
}

/* @arkzen:native:page:index:end */


/* @arkzen:native:page:about */

const AboutScreen = () => {
  const router = useRouter()
  const [count, setCount] = useState(0)

  return (
    <View className="flex-1 bg-neutral-50 px-6 pt-14 pb-10">

      {/* Back */}
      <GhostButton label="← Back" onPress={() => router.back()} />

      {/* Heading */}
      <View className="mt-8 mb-8">
        <Badge label="about" />
        <Text className="text-3xl font-bold text-neutral-900 mt-4">
          About this tatemono
        </Text>
        <Text className="text-sm text-neutral-500 mt-2 leading-6">
          A minimal native module scaffolded by the Arkzen engine. Pure React Native + NativeWind — no web code.
        </Text>
      </View>

      {/* Interactive counter — quick state smoke test */}
      <View className="bg-white rounded-2xl border border-neutral-100 p-6 items-center mb-6">
        <Text className="text-xs text-neutral-400 uppercase tracking-widest mb-2">
          State check
        </Text>
        <Text className="text-5xl font-bold text-indigo-500 mb-4">{count}</Text>
        <View className="flex-row gap-x-3">
          <TouchableOpacity
            onPress={() => setCount(c => Math.max(0, c - 1))}
            className="w-12 h-12 rounded-2xl bg-neutral-100 items-center justify-center"
          >
            <Text className="text-xl font-bold text-neutral-600">−</Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => setCount(c => c + 1)}
            className="w-12 h-12 rounded-2xl bg-indigo-500 items-center justify-center"
          >
            <Text className="text-xl font-bold text-white">+</Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* Stack info */}
      <View className="bg-neutral-100 rounded-2xl px-5 py-4">
        <Text className="text-xs font-mono text-neutral-500 leading-6">
          stack: expo{'\n'}
          engine: arkzen v10.1{'\n'}
          tatemono: hello-native{'\n'}
          screens: index, about
        </Text>
      </View>

    </View>
  )
}

/* @arkzen:native:page:about:end */

/* @arkzen:native:components:lynx:shared */

import { useState } from '@lynx-js/react'

// ── Pill badge ────────────────────────────────────────────────
const Badge = ({ label }: { label: string }) => (
  <view className="px-3 py-1 bg-indigo-100 rounded-full self-start">
    <text className="text-xs font-semibold text-indigo-600 tracking-wide">
      {label}
    </text>
  </view>
)

// ── Primary button ────────────────────────────────────────────
const PrimaryButton = ({
  label,
  onPress,
  disabled = false,
}: {
  label: string
  onPress: () => void
  disabled?: boolean
}) => (
  <view
    bindtap={disabled ? undefined : onPress}
    className={`rounded-2xl py-4 px-6 items-center ${
      disabled ? 'bg-indigo-200' : 'bg-indigo-500'
    }`}
  >
    <text className="text-white font-semibold text-base tracking-wide">
      {label}
    </text>
  </view>
)

// ── Ghost button ──────────────────────────────────────────────
const GhostButton = ({
  label,
  onPress,
}: {
  label: string
  onPress: () => void
}) => (
  <view
    bindtap={onPress}
    className="rounded-2xl py-4 px-6 items-center border border-neutral-200"
  >
    <text className="text-neutral-600 font-medium text-base">{label}</text>
  </view>
)

// ── Section card ──────────────────────────────────────────────
const Card = ({
  title,
  body,
}: {
  title: string
  body: string
}) => (
  <view className="bg-white rounded-2xl p-5 border border-neutral-100 mb-3">
    <text className="text-sm font-semibold text-neutral-800 mb-1">{title}</text>
    <text className="text-sm text-neutral-500 leading-5">{body}</text>
  </view>
)

/* @arkzen:native:components:lynx:shared:end */

/* @arkzen:native:page:lynx:index */

const IndexLynxScreen = () => {
  const [navigating, setNavigating] = useState(false)

  return (
    <view className="flex-1 bg-neutral-50 px-6 pt-14 pb-10">

      {/* Header */}
      <view className="mb-10">
        <Badge label="Arkzen Native v1.0" />
        <text className="text-4xl font-bold text-neutral-900 mt-4 leading-tight">
          {`Hello,\nNative. 👋`}
        </text>
        <text className="text-base text-neutral-500 mt-3 leading-6">
          Your first Arkzen native tatemono is running. Drop your UI in the native:page block.
        </text>
      </view>

      {/* Feature cards */}
      <view className="mb-8">
        <Card
          title="📦 Isolated module"
          body="This screen lives in tatemonos/hello-native/core.tsx — zero interference with other tatemonos."
        />
        <Card
          title="🎨 Tailwind styling"
          body="All className utilities available via the Lynx Tailwind preset. No inline style objects needed."
        />
        <Card
          title="⚡ Lynx runtime"
          body="Powered by @lynx-js/react — file-based routing auto-generated by the engine."
        />
      </view>

      {/* Actions */}
      <view className="gap-y-3">
        <PrimaryButton
          label="Go to About"
          onPress={() => setNavigating(true)}
          disabled={navigating}
        />
      </view>

    </view>
  )
}

/* @arkzen:native:page:lynx:index:end */

/* @arkzen:native:page:lynx:about */

const AboutLynxScreen = () => {
  const [count, setCount] = useState(0)

  return (
    <view className="flex-1 bg-neutral-50 px-6 pt-14 pb-10">

      {/* Back */}
      <GhostButton label="← Back" onPress={() => {}} />

      {/* Heading */}
      <view className="mt-8 mb-8">
        <Badge label="about" />
        <text className="text-3xl font-bold text-neutral-900 mt-4">
          About this tatemono
        </text>
        <text className="text-sm text-neutral-500 mt-2 leading-6">
