            results.map((r, i) => {
              const st = statusStyle(r.status)
              return (
                <View
                  key={r.id}
                  className={`px-5 py-3.5 flex-row items-center justify-between gap-3 ${
                    i < results.length - 1 ? 'border-b border-neutral-50' : ''
