import { useState, useEffect, useRef } from '@lynx-js/react'
import { arkzenFetch } from '@/arkzen/core/stores/authStore'
import { Icon } from '@/arkzen/core/components/Icon'
const BACKEND_URL = process.env.ARKZEN_BACKEND_URL ?? 'http://localhost:8000'

interface JobResult {
  id:           number
  job_name:     string
  status:       string
  result:       string | null
  processed_at: string | null
  created_at:   string
}

// status badge classes — dynamic status value, use inline bg color
const statusBg = (s: string) => ({
  completed:  '#dcfce7',
  processing: '#fef9c3',
  failed:     '#fee2e2',
}[s] ?? '#f5f5f5')

const statusText = (s: string) => ({
  completed:  '#15803d',
  processing: '#a16207',
  failed:     '#dc2626',
}[s] ?? '#525252')

// dot color — dynamic per job, use inline
const dotBg = (color: string) => ({
  blue:   '#3b82f6',
  purple: '#a855f7',
  red:    '#ef4444',
}[color] ?? '#a3a3a3')

